#!/bin/bash
# Write the qrscp config files for the two fake PACS.
#
# Why a generator: qrscp joins instance_location / database_location onto
# the folder of its own source file (site-packages/pynetdicom/apps/qrscp/),
# NOT onto the current directory. Relative paths therefore end up inside the
# virtualenv. Absolute paths are the safe choice, so we fill them in here.
set -euo pipefail
source "$(dirname "$0")/env.sh"
mkdir -p "$WORK/config" "$WORK/pacs_a" "$WORK/pacs_b"

write_cfg() { # name aet port
  cat > "$WORK/config/$1.ini" <<EOF
# qrscp configuration for fake PACS "$2" (generated by make_configs.sh)
[DEFAULT]
    # The AE title this fake PACS answers to (the "called AE title")
    ae_title: $2
    # TCP port to listen on
    port: $3
    # Largest PDU we accept; 0 = unlimited
    max_pdu: 16382
    acse_timeout: 30
    dimse_timeout: 30
    network_timeout: 30
    # Listen on loopback only (nothing outside this Mac can connect)
    bind_address: 127.0.0.1
    # MUST be absolute (see the comment at the top of make_configs.sh)
    instance_location: $WORK/$1/instances
    database_location: $WORK/$1/instances.sqlite
    log_identifier: True

## Known C-MOVE destinations: one section per AE title.
## Only AE titles listed here can be used as the Move Destination.
[EXPLORER]
    address: 127.0.0.1
    port: 11114

## A destination that is configured but has no listener (negative test:
## "receiver is down"). Nothing in the lab ever binds port 11119.
[OFFLINE]
    address: 127.0.0.1
    port: 11119

## The explorer app's own receiver (services/receiver.py), for C-MOVE from the app.
[DDE_EXPLORER]
    address: 127.0.0.1
    port: 11120
EOF
  echo "wrote $WORK/config/$1.ini"
}

write_cfg pacs_a PACS_A 11112
write_cfg pacs_b PACS_B 11113
